using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class C01WayfindingAudit {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var g=root.Find("C01_Experiment_Art/C01_Workplace_Wayfinding");var rr=g.GetComponentsInChildren<Renderer>();var meshes=g.GetComponentsInChildren<MeshFilter>().Select(f=>f.sharedMesh).Distinct().ToArray();int bad=0,tri=0;foreach(var m in meshes){var v=m.vertices;var t=m.triangles;for(int i=0;i<t.Length;i+=3){tri++;if(Vector3.Cross(v[t[i+1]]-v[t[i]],v[t[i+2]]-v[t[i]]).sqrMagnitude<1e-14f)bad++;}}var player=s.GetRootGameObjects().Single(o=>o.name.StartsWith("Player"));var result=new{scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,renderers=rr.Length,uniqueMeshes=meshes.Length,uniqueTriangles=tri,degenerateTriangles=bad,missingMaterials=rr.Sum(r=>r.sharedMaterials.Count(m=>!m||!m.shader)),newColliders=g.GetComponentsInChildren<Collider>(true).Length,newLights=g.GetComponentsInChildren<Light>(true).Length,newBehaviours=g.GetComponentsInChildren<MonoBehaviour>(true).Length,playerPosition=new[]{player.transform.position.x,player.transform.position.y,player.transform.position.z},playerRotation=new[]{player.transform.eulerAngles.x,player.transform.eulerAngles.y,player.transform.eulerAngles.z},runInBackground=PlayerSettings.runInBackground};File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_Wayfinding/geometry_audit.json")),JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
